export interface Course {
  id: number;
  name: string;
  island: 'North' | 'South';
  place_id: string;
  region: string;
  address: string;
  lat: number;
  lng: number;
  phone: string;
  price_min_nzd: number;
  price_max_nzd: number;
  tags: string[];
  opening_hours: string[];
  google_maps_url: string;
  rating: number;
  review_count: number;
  booking_url: string;
  website_url: string;
  image: string;
  description: string;
}

export interface Place {
  id: string;
  course_id: string;
  category: 'stay' | 'restaurant' | 'market' | 'golf_market' | 'golf_store' | 'tour_spot';
  name: string;
  address: string;
  lat: number;
  lng: number;
  rating: number;
  price_level: number;
  phone?: string;
  website_url?: string;
  distance_km: number;
}

export interface Round {
  id: string;
  course_id: string;
  course_name: string;
  played_at: string;
  players: string[];
  tee_type: string;
  total_score: number;
  front9_score?: number;
  back9_score?: number;
  putts_total?: number;
  notes: string;
  media: Media[];
}

export interface Media {
  id: string;
  type: 'photo' | 'video';
  url: string;
  thumbnail_url: string;
  caption: string;
}

export interface Challenge {
  id: string;
  type: string;
  title: { en: string; ko: string };
  description: { en: string; ko: string };
  icon: string;
  category: 'play' | 'nature' | 'fun' | 'team' | 'daily';
}

export interface Trip {
  id: string;
  name: string;
  start_date: string;
  end_date: string;
  base_city: string;
  members: string[];
  invite_token: string;
  created_at: string;
}

